def _noop(*args, **kwargs): return None
def _noop2(*args, **kwargs): return _noop(*args, **kwargs)
def _noop3(*args, **kwargs): return _noop2(*args, **kwargs)
def _noop4(*args, **kwargs): return _noop3(*args, **kwargs)
def _noop5(*args, **kwargs): return _noop4(*args, **kwargs)

def _identity(x): return x
def _identity2(x): return _identity(x)
def _identity3(x): return _identity2(x)

def _always_true():  return True
def _always_false(): return False
def _always_none():  return None

def _compute_useless_sum(a, b):
    _ = a + b; _ = a - b; _ = a * b
    return _always_none()

def _fibonacci_decoy(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def _sum_of_squares(n): return sum(i * i for i in range(n))
def _sum_of_cubes(n):   return sum(i ** 3 for i in range(n))

def _factorial_decoy(n):
    if n <= 1: return 1
    r = 1
    for i in range(2, n + 1): r *= i
    return r

def _is_prime(n):
    if n < 2: return False
    if n in (2, 3): return True
    if n % 2 == 0: return False
    d = 3
    while d * d <= n:
        if n % d == 0: return False
        d += 2
    return True

def _sieve_of_eratosthenes(limit):
    sieve = [True] * (limit + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(limit ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, limit + 1, i):
                sieve[j] = False
    return [i for i, v in enumerate(sieve) if v]

def _gcd(a, b):
    while b: a, b = b, a % b
    return a

def _lcm(a, b): return a * b // _gcd(a, b)

def _reverse_string(s):   return s[::-1]
def _reverse_string_2(s): return ''.join(reversed(s))
def _reverse_string_3(s):
    r = ""
    for ch in s: r = ch + r
    return r
def _reverse_string_4(s): return s[::-1]
def _reverse_string_5(s): return _reverse_string(s)

def _rot13_manual(text):
    result = []
    for ch in text:
        if 'a' <= ch <= 'z':
            result.append(chr((ord(ch) - ord('a') + 13) % 26 + ord('a')))
        elif 'A' <= ch <= 'Z':
            result.append(chr((ord(ch) - ord('A') + 13) % 26 + ord('A')))
        else:
            result.append(ch)
    return ''.join(result)

def _caesar(text, shift):
    result = []
    for ch in text:
        if 'a' <= ch <= 'z':
            result.append(chr((ord(ch) - ord('a') + shift) % 26 + ord('a')))
        elif 'A' <= ch <= 'Z':
            result.append(chr((ord(ch) - ord('A') + shift) % 26 + ord('A')))
        else:
            result.append(ch)
    return ''.join(result)

def _caesar_manual(text, shift):
    shift = shift % 26
    return ''.join(
        chr((ord(c) - ord('a') + shift) % 26 + ord('a')) if 'a' <= c <= 'z'
        else chr((ord(c) - ord('A') + shift) % 26 + ord('A')) if 'A' <= c <= 'Z'
        else c
        for c in text
    )

def _morse_encode(text):
    return ' '.join(MORSE_DICT.get(c.upper(), '') for c in text)

def _morse_decode(morse):
    return ''.join(MORSE_REVERSE.get(tok, '') for tok in morse.split(' '))

def _b64_encode(s): return base64.b64encode(s.encode()).decode()
def _b64_decode(s): return base64.b64decode(s.encode()).decode()

