class _AnotherUseless:
    def __init__(self, x=None, y=None, z=None):
        self.x = x
        self.y = y
        self.z = z
    def __repr__(self):
        return f"_AnotherUseless(x={self.x!r}, y={self.y!r}, z={self.z!r})"
    def __str__(self):  return self.__repr__()
    def __eq__(self, other):
        return isinstance(other, _AnotherUseless) and (self.x, self.y, self.z) == (other.x, other.y, other.z)
    def __hash__(self): return hash((self.x, self.y, self.z))
    def __bool__(self): return False

class _CipherRegistry:
    REGISTRY = {}
    @classmethod
    def register(cls, name, fn):
        cls.REGISTRY[name] = fn
        return fn
    @classmethod
    def get(cls, name): return cls.REGISTRY.get(name)
    @classmethod
    def all(cls):       return dict(cls.REGISTRY)

class _UselessContext:
    def __enter__(self):  return self
    def __exit__(self, *args): return False

