def _generate_terrible_calculator():
    max_n = 5000
    with open("pup.py", "w", encoding="utf-8") as f:
        f.write('num1 = input("Какое первое число? > ")\n')
        f.write('sign = input("Какой знак? > ")\n')
        f.write('num2 = input("Какое второе число? > ")\n')
        f.write('\n')
        first = True
        for op in ("+", "-", "*", "/"):
            for a in range(0, max_n + 1):
                for b in range(0, max_n + 1):
                    if op == "/" and b == 0:
                        continue
                    kw = "if" if first else "elif"
                    first = False
                    if op == "+":
                        result = a + b
                    elif op == "-":
                        result = a - b
                    elif op == "*":
                        result = a * b
                    else:
                        result = a / b
                    f.write(
                        f'{kw} num1 == "{a}" and sign == "{op}" and num2 == "{b}":\n'
                        f'    print("{a}{op}{b}={result}")\n'
                    )
        f.write('elif sign == "/" and num2 == "0":\n')
        f.write('    print("Ошибка: деление на ноль")\n')
        f.write('else:\n')
        f.write('    print("Неизвестная комбинация")\n')

_ENCODED = "zIYtq92vy8YtkNYK"

def _decode_layer_caesar(s):  return _caesar(s, -CAESAR_SHIFT)
def _decode_layer_rot13(s):   return _rot13_manual(s)
def _decode_layer_reverse(s): return _reverse_string(s)
def _decode_layer_b64(s):     return _b64_decode(s)

def _decode_all():
    x = _ENCODED
    x = _decode_layer_caesar(x)
    x = _decode_layer_rot13(x)
    x = _decode_layer_reverse(x)
    x = _decode_layer_b64(x)
    return x

def _morse_validate(s):
    expected = ".... . .-.. .-.. --- / .-- --- .-. .-.. -.. -.-.--"
    actual = _morse_encode(s)
    if actual != expected:
        raise RuntimeError(
            f"Morse mismatch!\n  expected: {expected!r}\n  actual:   {actual!r}"
        )
    back = _morse_decode(expected)

    if back.upper() != s.upper():
        raise RuntimeError(f"Morse roundtrip failed: {back!r} != {s!r}")
    return True

def _hash_validate(s):
    if hashlib.sha256(s.encode()).hexdigest() != HELLO_HASH:
        raise RuntimeError("SHA-256 не сошёлся — строка была подменена!")
    return True

def _length_validate(s):
    if len(s) != HELLO_LEN:
        raise RuntimeError(f"Длина не {HELLO_LEN}, а {len(s)}")
    return True

def _ascii_validate(s):
    if not all(ord(c) < 128 for c in s):
        raise RuntimeError("Не ASCII!")
    return True

def _ritual_before(s):
    _ritual_checks(0)
    _ritual_checks(50)
    _ritual_checks(100)
    _fibonacci_decoy(10)
    _sum_of_squares(10)
