def __never_called():
    _ = _noop(_USELESS_LIST, _USELESS_DICT, _USELESS_SET)
    _ = _noop2(_USELESS_TUPLE, _USELESS_STR, _USELESS_BYTES)
    _ = _noop3(_USELESS_HASH, _USELESS_REVERSE, _USELESS_CAESAR)
    _ = _noop4(_USELESS_MORSE, _USELESS_B64, _USELESS_FIB)
    _ = _noop5(_USELESS_PRIMES)
    return None

_LOAD_CPU_SECONDS = 0.4
_LOAD_RAM_MB      = 25
_LOAD_RAM_SECONDS = 0.2
_LOAD_GPU_SHAPES  = 200
_LOAD_GPU_SECONDS = 0.15

def _brief_cpu_load():
    deadline = time.perf_counter() + _LOAD_CPU_SECONDS
    acc = 0.0; i = 0
    while time.perf_counter() < deadline:
        acc += math.sqrt(i + 1) * math.sin(i % 360)
        acc -= math.cos(i % 180)
        acc += math.log1p(i % 1000)
        i += 1
    return {"iterations": i, "acc": acc}

def _brief_ram_load():
    target_bytes = _LOAD_RAM_MB * 1024 * 1024
    chunk = [0] * (target_bytes // 8)
    for i in range(0, len(chunk), 1024):
        chunk[i] = i
    time.sleep(_LOAD_RAM_SECONDS)
    del chunk; gc.collect()
    return {"allocated_mb": _LOAD_RAM_MB}

def _brief_gpu_load():

    deadline = time.perf_counter() + _LOAD_GPU_SECONDS
    size = 32
    a = [[float(i * size + j) for j in range(size)] for i in range(size)]
    b = [[1.0 if i == j else 0.0 for j in range(size)] for i in range(size)]
    result = [[0.0] * size for _ in range(size)]
    iterations = 0
    while time.perf_counter() < deadline:
        for i in range(size):
            for j in range(size):
                s = 0.0
                for k in range(size):
                    s += a[i][k] * b[k][j]
                result[i][j] = s
        iterations += 1
    return {"mode": "emulated", "iterations": iterations}

def _brief_system_load():
    _brief_cpu_load()
    _brief_ram_load()
    _brief_gpu_load()
    return True

