def _morse_encode_multi(text, table):
    return ' '.join(table.get(ch.upper(), table.get(ch, '')) for ch in text)

def _morse_decode_multi(morse, table):
    reverse = {v: k for k, v in table.items()}
    return ''.join(reverse.get(tok, '') for tok in morse.split(' '))

def _caesar_multi(text, shift, alphabet):
    n = len(alphabet)
    if n == 0: return text
    result = []
    for ch in text:
        low = ch.lower()
        if low in alphabet:
            i = alphabet.index(low)
            new = alphabet[(i + shift) % n]
            result.append(new.upper() if ch.isupper() else new)
        else:
            result.append(ch)
    return ''.join(result)

def _multi_language_self_test():
    morse_samples = [
        (
            "Latin",    
            "SOS",        
            MORSE_DICT),
        (
            "Cyrillic", 
            "привет",     
            CYRILLIC_MORSE
            ),
        (
            "Greek",    
            "γεια",       
            GREEK_MORSE
            ),
        (
            "Hebrew",   
            "אבג",        
            HEBREW_MORSE
            ),
        (
            "Arabic",   
            "مرحبا",      
            ARABIC_MORSE
            ),
        (
            "Japanese", 
            "コンニチハ", 
            JAPANESE_WABUN),
    ]
    for name, sample, table in morse_samples:
        encoded = _morse_encode_multi(sample, table)
        decoded = _morse_decode_multi(encoded, table)
        if decoded.upper() != sample.upper():
            raise RuntimeError(
                f"[Morse/{name}] roundtrip failed: "
                f"{sample!r} -> {encoded!r} -> {decoded!r}"
            )

    caesar_samples = [
        (
            "Russian",    
            RUSSIAN_ALPHABET,    
            "привет"
            ),
        (
            "Greek",
            GREEK_ALPHABET,      
            "γειά"
            ),
        (
            "Hebrew",     
            HEBREW_ALPHABET,     
            "שלום"
            ),
        (
            "Arabic",     
            ARABIC_ALPHABET,     
            "مرحبا"
            ),
        (
            "Armenian",   
            ARMENIAN_ALPHABET,   
            "բարեւ"
            ),
        (
            "Georgian",   
            GEORGIAN_ALPHABET,   
            "გამარჯობა"
            ),
        (
            "Devanagari", 
            DEVANAGARI_ALPHABET, 
            "नमस्ते"
            ),
        (
            "Thai",       
            THAI_ALPHABET,       
            "สวัสดี"
            ),

        (
            "Korean",     
            KOREAN_HANGUL,       
            "ㅇㅏㄴㄴㅕㅇ"
            ),
    ]
    for name, alphabet, sample in caesar_samples:
        enc = _caesar_multi(sample, 5, alphabet)
        dec = _caesar_multi(enc, -5, alphabet)
        if dec != sample:
            raise RuntimeError(
                f"[Caesar/{name}] roundtrip failed: "
                f"{sample!r} -> {enc!r} -> {dec!r}"
            )

    return {
        "morse_languages":  [name for name, _, _ in morse_samples],
        "caesar_languages": [name for name, _, _ in caesar_samples],
    }

