def _validate_ascii_arts():
    if not isinstance(ASCII_ART_HELLO, list):
        raise RuntimeError("ASCII_ART_HELLO должен быть списком!")
    if len(ASCII_ART_HELLO) == 0:
        raise RuntimeError("Список ASCII_ART_HELLO пуст!")
    for i, art in enumerate(ASCII_ART_HELLO):
        if not isinstance(art, str):
            raise RuntimeError(f"ASCII_ART_HELLO[{i}] — не строка!")
        if len(art.strip()) == 0:
            raise RuntimeError(f"ASCII_ART_HELLO[{i}] пустой после strip()!")
    return len(ASCII_ART_HELLO)

def _pick_random_ascii_hello():
    if not ASCII_ART_HELLO:
        return "Hello world!"
    return rnd.choice(ASCII_ART_HELLO).strip('\n')

def _ritual_ascii_before_output():
    count = _validate_ascii_arts()
    _ritual_checks(count)
    _ = _noop(ASCII_ART_HELLO)
    return count

def _physics_roll_die(n_faces):
    if n_faces <= 0: return 0
    if n_faces == 1: return 0

    g            = 9.81 + rnd.uniform(-0.05, 0.05)
    air_density  = 1.225 * rnd.uniform(0.95, 1.05)         
    dt           = 0.005

    x = rnd.uniform(-2, 2)
    y = rnd.uniform(-2, 2)
    z = rnd.uniform(3, 8)

    speed0 = rnd.uniform(2, 9)
    theta  = rnd.uniform(0, 2 * math.pi)
    phi    = rnd.uniform(-math.pi / 4, math.pi / 4)
    vx = speed0 * math.cos(phi) * math.cos(theta)
    vy = speed0 * math.cos(phi) * math.sin(theta)
    vz = speed0 * math.sin(phi)

    pitch = rnd.uniform(0, 2 * math.pi)
    roll  = rnd.uniform(0, 2 * math.pi)
    yaw   = rnd.uniform(0, 2 * math.pi)
    spin_pitch = rnd.uniform(-15, 15)
    spin_roll  = rnd.uniform(-15, 15)
    spin_yaw   = rnd.uniform(-15, 15)

    wind_angle = rnd.uniform(0, 2 * math.pi)
    wind_base  = rnd.uniform(0, 2)
    gusts = [
        (rnd.uniform(0, 3), rnd.uniform(2, 8),
         rnd.uniform(0.1, 0.5), rnd.uniform(-0.6, 0.6))
        for _ in range(rnd.randint(2, 5))
    ]

    def wind_at(t):
        wx = wind_base * math.cos(wind_angle)
        wy = wind_base * math.sin(wind_angle)
        for ts, mag, dur, da in gusts:
            if ts <= t <= ts + dur:
                env = math.sin((t - ts) / dur * math.pi)
                ga  = wind_angle + da
                wx += mag * env * math.cos(ga)
                wy += mag * env * math.sin(ga)
        return wx, wy

    floors = {
        "wood":     {
            "rest": 0.5,  
            "fric": 0.5 
            },
        "carpet":   {
            "rest": 0.1,  
            "fric": 0.9 
            },
        "tile":     {
            "rest": 0.7,  
            "fric": 0.3 
            },
        "grass":    {
            "rest": 0.2,  
            "fric": 0.7 
            },
        "sand":     {
            "rest": 0.05, 
            "fric": 0.95
            },
        "concrete": {
            "rest": 0.8,  
            "fric": 0.4 
            },
        "rubber":   {
            "rest": 0.9,  
            "fric": 0.8 
            },
        "ice":      {
            "rest": 0.4,  
            "fric": 0.05
            },
        "moon":     {
            "rest": 0.3,  
            "fric": 0.3 
            },
    }
    floor_name = rnd.choice(list(floors))
    floor      = floors[floor_name]
    restitution_floor = floor["rest"] * rnd.uniform(0.9, 1.1)
    friction_floor    = floor["fric"]

    walls_x   = rnd.uniform(4, 6)
    walls_y   = rnd.uniform(4, 6)
    wall_rest = rnd.uniform(0.3, 0.7)

    t = 0.0
    bounces = 0
    for _step in range(20000):
        wx, wy = wind_at(t)

        v_mag = math.sqrt(vx*vx + vy*vy + vz*vz)
        k_drag = 0.5 * air_density * 0.01
        ax = -k_drag * v_mag * vx + wx * 0.3
        ay = -k_drag * v_mag * vy + wy * 0.3
        az = -g - k_drag * v_mag * vz

        vx += ax * dt; vy += ay * dt; vz += az * dt
        x  += vx * dt; y  += vy * dt; z  += vz * dt

        pitch += spin_pitch * dt
        roll  += spin_roll  * dt
        yaw   += spin_yaw   * dt

        if z < 0.0:
            z  = 0.0
            vz = -vz * restitution_floor
            vx *= (1.0 - friction_floor * 0.3)
            vy *= (1.0 - friction_floor * 0.3)
            spin_pitch += rnd.uniform(-5, 5)
            spin_roll  += rnd.uniform(-5, 5)
            spin_yaw   += rnd.uniform(-5, 5)
            bounces += 1

        if abs(x) > walls_x:
            x  = math.copysign(walls_x, x)
            vx = -vx * wall_rest
            spin_roll += rnd.uniform(-3, 3)
            spin_yaw  += rnd.uniform(-3, 3)
        if abs(y) > walls_y:
            y  = math.copysign(walls_y, y)
            vy = -vy * wall_rest
            spin_pitch += rnd.uniform(-3, 3)
            spin_yaw   += rnd.uniform(-3, 3)

        v2 = vx*vx + vy*vy + vz*vz
        s2 = spin_pitch**2 + spin_roll**2 + spin_yaw**2
        if z < 0.01 and v2 < 0.1 and s2 < 0.5:
            break

        t += dt

    state = (
        round(pitch, 4), round(roll, 4), round(yaw, 4),
        round(x, 4), round(y, 4), round(z, 4),
        round(vx, 3), round(vy, 3), round(vz, 3),
        bounces, round(t, 4), floor_name,
    )
    digest = hashlib.sha256(str(state).encode()).digest()
    return int.from_bytes(digest[:4], "big") % n_faces

def _pick_ascii_by_physics():
    n = len(ASCII_ART_HELLO)
    face = _physics_roll_die(n)
    return ASCII_ART_HELLO[face].strip('\n')

def _physics_roll_die(n_faces):
    if n_faces <= 0: return 0, [], "void", {}
    if n_faces == 1: return 0, [], "void", {}

    g            = 9.81 + rnd.uniform(-0.05, 0.05)
    air_density  = 1.225 * rnd.uniform(0.95, 1.05)
    dt           = 0.005

    x = rnd.uniform(-1.5, 1.5)
    y = rnd.uniform(-1.5, 1.5)
    z = rnd.uniform(4, 8)

    speed0 = rnd.uniform(2, 7)
    theta  = rnd.uniform(0, 2 * math.pi)
    phi    = rnd.uniform(-math.pi / 4, math.pi / 4)
    vx = speed0 * math.cos(phi) * math.cos(theta)
    vy = speed0 * math.cos(phi) * math.sin(theta)
    vz = speed0 * math.sin(phi)

    pitch = rnd.uniform(0, 2 * math.pi)
    roll  = rnd.uniform(0, 2 * math.pi)
    yaw   = rnd.uniform(0, 2 * math.pi)
    spin_pitch = rnd.uniform(-12, 12)
    spin_roll  = rnd.uniform(-12, 12)
    spin_yaw   = rnd.uniform(-12, 12)

    wind_angle = rnd.uniform(0, 2 * math.pi)
    wind_base  = rnd.uniform(0, 2)
    gusts = [(rnd.uniform(0, 3), rnd.uniform(2, 8),
              rnd.uniform(0.1, 0.5), rnd.uniform(-0.6, 0.6))
             for _ in range(rnd.randint(2, 5))]

    def wind_at(t):
        wx = wind_base * math.cos(wind_angle)
        wy = wind_base * math.sin(wind_angle)
        for ts, mag, dur, da in gusts:
            if ts <= t <= ts + dur:
                env = math.sin((t - ts) / dur * math.pi)
                ga  = wind_angle + da
                wx += mag * env * math.cos(ga)
                wy += mag * env * math.sin(ga)
        return wx, wy

    floors = {
        "дерево":  {
            "rest": 0.5,  
            "fric": 0.5 
            },
        "ковёр":   {
            "rest": 0.1,  
            "fric": 0.9 
            },
        "плитка":  {
            "rest": 0.7,  
            "fric": 0.3 
            },
        "трава":   {
            "rest": 0.2,  
            "fric": 0.7 
            },
        "песок":   {
            "rest": 0.05, 
            "fric": 0.95
            },
        "бетон":   {
            "rest": 0.8,  
            "fric": 0.4 
            },
        "резина":  {
            "rest": 0.9,  
            "fric": 0.8 
            },
        "лёд":     {
            "rest": 0.4,  
            "fric": 0.05
            },
        "Луна":    {
            "rest": 0.3,  
            "fric": 0.3 
            },
    }
    floor_name = rnd.choice(list(floors))
    floor      = floors[floor_name]
    restitution_floor = floor["rest"] * rnd.uniform(0.9, 1.1)
    friction_floor    = floor["fric"]

    walls = 3.5
    wall_rest = rnd.uniform(0.3, 0.7)

    t = 0.0
    bounces = 0
    keyframes = []
    RECORD_EVERY = 4

    MAX_STEPS    = 4000
    MAX_BOUNCES  = 40
    GROUND_Z     = 0.02
    SPIN_GROUND_DAMP = 0.88
    VEL_GROUND_DAMP  = 0.95

    for step in range(MAX_STEPS):
        wx, wy = wind_at(t)
        v_mag = math.sqrt(vx*vx + vy*vy + vz*vz)
        k_drag = 0.5 * air_density * 0.01
        ax = -k_drag * v_mag * vx + wx * 0.3
        ay = -k_drag * v_mag * vy + wy * 0.3
        az = -g - k_drag * v_mag * vz

        vx += ax * dt; vy += ay * dt; vz += az * dt
        x  += vx * dt; y  += vy * dt; z  += vz * dt
        pitch += spin_pitch * dt
        roll  += spin_roll  * dt
        yaw   += spin_yaw   * dt

        if z < 0.0:
            z = 0.0
            if abs(vz) < 0.2:
                vz = 0.0
            else:
                vz = -vz * restitution_floor
            vx *= (1.0 - friction_floor * 0.5)
            vy *= (1.0 - friction_floor * 0.5)
            impact_damp = 0.4 + 0.6 * friction_floor
            spin_pitch *= impact_damp
            spin_roll  *= impact_damp
            spin_yaw   *= impact_damp
            bounces += 1

        if z < GROUND_Z:
            spin_pitch *= SPIN_GROUND_DAMP
            spin_roll  *= SPIN_GROUND_DAMP
            spin_yaw   *= SPIN_GROUND_DAMP
            vx *= VEL_GROUND_DAMP
            vy *= VEL_GROUND_DAMP
            if abs(vz) < 0.05:
                vz = 0.0

        if abs(x) > walls:
            x  = math.copysign(walls, x)
            vx = -vx * wall_rest
            spin_roll *= 0.7
            spin_yaw  *= 0.7
        if abs(y) > walls:
            y  = math.copysign(walls, y)
            vy = -vy * wall_rest
            spin_pitch *= 0.7
            spin_yaw   *= 0.7

        if step % RECORD_EVERY == 0:

            keyframes.append((t * 1000.0, x, y, z, pitch, roll, yaw))

        v2 = vx*vx + vy*vy + vz*vz
        s2 = spin_pitch**2 + spin_roll**2 + spin_yaw**2
        if z < GROUND_Z and v2 < 0.05 and s2 < 0.5:
            keyframes.append((t * 1000.0, x, y, z, pitch, roll, yaw))
            break
        if bounces >= MAX_BOUNCES:
            keyframes.append((t * 1000.0, x, y, z, pitch, roll, yaw))
            break

        t += dt

    MAX_KF = 250
    if len(keyframes) > MAX_KF:
        idxs = [int(i * (len(keyframes) - 1) / (MAX_KF - 1))
                for i in range(MAX_KF)]
        keyframes = [keyframes[i] for i in idxs]

    state = (round(pitch,4), round(roll,4), round(yaw,4),
             round(x,4), round(y,4), round(z,4),
             round(vx,3), round(vy,3), round(vz,3),
             bounces, round(t,4), floor_name)
    digest = hashlib.sha256(str(state).encode()).digest()
    face = int.from_bytes(digest[:4], "big") % n_faces

    meta = {
        "gravity":         round(g, 4),
        "air_density":     round(air_density, 4),
        "wind_base":       round(wind_base, 4),
        "wind_angle":      round(wind_angle, 4),
        "gusts":           [[round(a,4), round(b,4), round(c,4), round(d,4)]
                            for a, b, c, d in gusts],
        "floor":           floor_name,
        "restitution":     round(restitution_floor, 4),
        "friction":        round(friction_floor, 4),
        "walls":           walls,
        "wall_restitution": round(wall_rest, 4),
        "bounces":         bounces,
        "total_ms":        round(t * 1000.0, 3),
        "dt_ms":           round(dt * 1000.0, 3),
        "start": {
            "x": round(x, 4), "y": round(y, 4), "z": round(z, 4),
            "pitch": round(pitch, 4), "roll": round(roll, 4), "yaw": round(yaw, 4),
        },
    }
    return face, keyframes, floor_name, meta

def _animate_die_3d(keyframes, n_faces, floor_name, duration_ms=2500):
    import tkinter as tk

    W, H = 640, 520
    root = tk.Tk()
    root.title(f"D{n_faces} → {floor_name}")
    canvas = tk.Canvas(root, width=W, height=H, bg="#0a0a1e",
                       highlightthickness=0)
    canvas.pack()

    s = 0.5
    verts = [
        (-s,-s,-s), ( s,-s,-s), ( s, s,-s), (-s, s,-s),
        (-s,-s, s), ( s,-s, s), ( s, s, s), (-s, s, s),
    ]
    faces = [
        (0,1,2,3), (4,5,6,7), (0,1,5,4),
        (2,3,7,6), (0,3,7,4), (1,2,6,5),
    ]
    face_colors = ["#e74c3c","#3498db","#2ecc71",
                   "#f39c12","#9b59b6","#1abc9c"]

    scale   = 70
    center_x = W / 2
    floor_y  = H - 70

    def rotate(v, ax, ay, az):
        x, y, z = v
        c, s_ = math.cos(ax), math.sin(ax)
        y, z = y*c - z*s_, y*s_ + z*c
        c, s_ = math.cos(ay), math.sin(ay)
        x, z = x*c + z*s_, -x*s_ + z*c
        c, s_ = math.cos(az), math.sin(az)
        x, y = x*c - y*s_, x*s_ + y*c
        return (x, y, z)

    def project(vx, vy, vz, px, py, pz):

        wx = vx + px
        wy = vy + py
        wz = vz + pz

        sx = center_x + wx * scale
        sy = floor_y - wz * scale + wy * scale * 0.35
        return sx, sy, wy

    def draw_frame(state):

        _, x, y, z, pitch, roll, yaw = state
        canvas.delete("all")

        canvas.create_rectangle(0, floor_y, W, H, fill="#15152a", outline="")
        canvas.create_line(0, floor_y, W, floor_y, fill="#ff6b6b", width=2)
        canvas.create_text(20, 20, text=f"Поверхность: {floor_name}",
                           fill="#aaaaaa", anchor="nw",
                           font=("Consolas", 11))
        canvas.create_text(20, 42, text=f"z = {z:.2f} м",
                           fill="#888888", anchor="nw",
                           font=("Consolas", 10))

        shadow_r = max(6, 35 * (1 - z / 12))
        sx = center_x + x * scale
        canvas.create_oval(sx - shadow_r, floor_y - shadow_r/2,
                           sx + shadow_r, floor_y + shadow_r/2,
                           fill="#000", outline="")

        rot = [rotate(v, pitch, roll, yaw) for v in verts]
        proj = [project(*v, x, y, z) for v in rot]
        face_data = []
        for i, face in enumerate(faces):
            pts = [(proj[j][0], proj[j][1]) for j in face]
            avg_depth = sum(proj[j][2] for j in face) / 4
            face_data.append((avg_depth, i, pts))

        face_data.sort(key=lambda f: -f[0])
        for depth, i, pts in face_data:
            flat = [c for p in pts for c in p]
            canvas.create_polygon(flat, fill=face_colors[i],
                                  outline="#000", width=1)

    if not keyframes:
        root.destroy()
        return

    idx = [0]
    total_ms = max(500, duration_ms)
    delay_per_frame = max(10, total_ms // max(1, len(keyframes)))

    hard_deadline = time.time() + 6.0

    def step():

        if idx[0] >= len(keyframes) or time.time() > hard_deadline:
            root.after(400, root.destroy)
            return
        draw_frame(keyframes[idx[0]])
        idx[0] += 1
        root.after(delay_per_frame, step)

    root.after(80, step)
    root.mainloop()

def _animate_die_3d_safe(keyframes, n_faces, floor_name):
    try:
        _animate_die_3d(keyframes, n_faces, floor_name)
        return True
    except Exception:
        return False

def _save_keyframes_to_json(keyframes, n_faces, face_index, floor_name, meta):
    if not keyframes:
        return None

    fname = "die_roll.json"
    entry = {
        "saved_at":   datetime.datetime.now().isoformat(timespec="milliseconds"),
        "n_faces":    n_faces,
        "face_index": face_index,
        "floor":      floor_name,
        "meta":       meta,
        "keyframe_count": len(keyframes),
        "keyframes": [
            {"t_ms": round(kf[0],3), "x": round(kf[1],6), "y": round(kf[2],6),
             "z": round(kf[3],6), "pitch": round(kf[4],6),
             "roll": round(kf[5],6), "yaw": round(kf[6],6)}
            for kf in keyframes
        ],
    }
    try:
        history = []
        if os.path.exists(fname):
            try:
                with open(fname, "r", encoding="utf-8") as f:
                    old = json.load(f)
                if isinstance(old, list):
                    history = old
                elif isinstance(old, dict):
                    history = [old]
            except Exception:
                history = []
        history.append(entry)
        with open(fname, "w", encoding="utf-8") as f:
            json.dump(history, f, indent=2, ensure_ascii=False)
        return fname
    except Exception:
        return None

